const std = @import("std");

const HuffNode = struct {
    ch: u8,
    freq: u32,
    left: ?*HuffNode,
    right: ?*HuffNode,
};

pub fn main() !void {
    var n_a = HuffNode{ .ch = 'a', .freq = 5, .left = null, .right = null };
    var n_b = HuffNode{ .ch = 'b', .freq = 9, .left = null, .right = null };
    var n_c = HuffNode{ .ch = 'c', .freq = 12, .left = null, .right = null };
    var n_d = HuffNode{ .ch = 'd', .freq = 13, .left = null, .right = null };
    var n_e = HuffNode{ .ch = 'e', .freq = 16, .left = null, .right = null };
    var n_f = HuffNode{ .ch = 'f', .freq = 45, .left = null, .right = null };

    var n1 = HuffNode{ .ch = 0, .freq = n_a.freq + n_b.freq, .left = &n_a, .right = &n_b };
    var n2 = HuffNode{ .ch = 0, .freq = n_c.freq + n_d.freq, .left = &n_c, .right = &n_d };
    var n3 = HuffNode{ .ch = 0, .freq = n1.freq + n_e.freq, .left = &n1, .right = &n_e };
    var n4 = HuffNode{ .ch = 0, .freq = n2.freq + n3.freq, .left = &n2, .right = &n3 };
    var root = HuffNode{ .ch = 0, .freq = n4.freq + n_f.freq, .left = &n4, .right = &n_f };

    std.debug.print("Root freq: {}\n", .{root.freq});
    std.debug.print("Left freq: {}\n", .{root.left.?.freq});
    std.debug.print("Right freq: {}\n", .{root.right.?.freq});
}
